class CustomMoneyPunct : public std::moneypunct<char> {
public:
    static std::locale::id id;
protected:
    char do_decimal_point() const override { return ','; }
    std::string do_curr_symbol() const override { return "EUR"; }
    // Grouping: 3 digits standard
    std::string do_grouping() const override { return "\003"; }
};
std::locale::id CustomMoneyPunct::id;

// Creation: Locale initialized with custom facet
std::locale custom_monetary_loc(
    std::locale::classic(),
    new CustomMoneyPunct
);

